import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find features with strong associations (p < 0.05, |t| > 2)
    strong_features = []
    for i, fid in enumerate(feats.ids):
        # Use the actual t-statistic from feats.types if available
        t_stat = feats.types[i]
        if isinstance(t_stat, (int, float)) and abs(t_stat) > 2:
            # Check if this is an expression-like feature (assuming positive values indicate expression)
            # We'll just use the absolute t-statistic to determine significance
            strong_features.append(fid)

    # Remove near-duplicates (correlated pairs with |r| >= 0.6)
    correlated_pairs = set()
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids):
            if i >= j:
                continue
            corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0,1]
            if abs(corr) >= 0.6:
                correlated_pairs.add((min(fid1, fid2), max(fid1, fid2)))

    # Keep one feature from each correlated pair
    unique_features = set(strong_features)
    for p1, p2 in correlated_pairs:
        if p1 in unique_features and p2 in unique_features:
            unique_features.remove(p2)  # Remove second

    # Try product terms between top features
    top_features = list(unique_features)[:10]  # Top 10 features
    best_product = None
    best_p = 1.0

    for i, f1 in enumerate(top_features):
        for j, f2 in enumerate(top_features):
            if i >= j:
                continue
            col1 = feats.column(f1)
            col2 = feats.column(f2)
            product = feats.x[:, col1] * feats.x[:, col2]

            # Test association with outcome
            t_stat, p_val = stats.ttest_1samp(product[feats.y==1], 
                                            product[feats.y==0])
            if p_val < best_p:
                best_p = p_val
                best_product = (f1, f2)

    # If significant product term found, use it
    if best_product and best_p < 0.05:
        return Design(
            drivers=(),
            columns=list(best_product),
            products=[best_product],
            loadings={}
        )

    # Otherwise, select strongest single features
    drivers = []
    columns = []
    loadings = {}

    # Sort by t-statistic (absolute value)
    t_stats = []
    for fid in unique_features:
        idx = feats.column(fid)
        t_stat = feats.types[idx]
        if isinstance(t_stat, (int, float)):
            t_stats.append(abs(t_stat))
        else:
            t_stats.append(0)

    sorted_indices = np.argsort(t_stats)[::-1][:MAX_DRIVERS]

    for i in sorted_indices:
        if i < len(unique_features):
            fid = list(unique_features)[i]
            drivers.append(fid)
            columns.append(fid)
            loadings[fid] = feats.types[feats.column(fid)]

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=(),
        loadings=loadings
    )

